            '                    if (_carouselProduct.length == 0) {\n' +
            '                        return;\n' +
            '                    }\n' +
            '\n' +
            '                    var impression_products = [];\n' +
            '                    _carouselProduct.each(function (index, prd) {\n' +
            '                        var _prdJson = $(prd).data(\'gtmCarouselProduct\');\n' +
            '                        impression_products.push(_prdJson);\n' +
            '                    });\n' +
            '                    ACC.pentiGTM.object.carousel = impression_products;\n' +
            '                    dataLayer.push({\n' +
            '                        \'event\': \'productImpression\',\n' +
            '                        \'ecommerce\': {\n' +
            '                            \'impressions\': impression_products\n' +
            '                        }\n' +
            '                    });\n' +
            '                }\n' +
            '            </' + 'script>').appendTo(document.body);
        readyForGtm();
    }, 2750);
});
}
























